-- STARTER CATALOGUE: 8 categories + 133 products (no prices yet).
-- Run in Supabase: SQL Editor > New query > paste > Run. Safe to run again: categories and products that already exist (same name) are skipped.
-- Photos are served from the site itself (public/products), so deploy the site with the new photos first.
-- Every product starts at price 0, which the shop shows as "Price on request". Set real prices in Admin > Products.

insert into categories (name, image_url, sort)
select v.name, v.image_url, v.sort from (values
  ('Chandeliers', '/products/glass-leaf-round-chandelier-76583.jpg', 1),
  ('LED Dining Lights', '/products/zig-zag-led-dining-light-76710.jpg', 2),
  ('Pendant Lights', '/products/black-dome-pendant-light-76803.jpg', 3),
  ('Wall Lights', '/products/moon-round-led-wall-light-76693.jpg', 4),
  ('Outdoor & Street Lights', '/products/led-street-light-76660.jpg', 5),
  ('Table Lamps', '/products/gold-dome-mushroom-table-lamp-76611.jpg', 6),
  ('Floor Lamps', '/products/brass-dome-arc-floor-lamp-76617.jpg', 7),
  ('Ceiling & Spot Lights', '/products/black-surface-mounted-cob-spotlights-76821.jpg', 8)
) as v(name, image_url, sort)
where not exists (select 1 from categories c where c.name = v.name);

insert into products (name, category_id, price, stock_status, description, specs, images, featured, is_new, visible, created_at)
select v.name, (select c.id from categories c where c.name = v.cat order by c.sort, c.id limit 1), 0, 'on_request', v.name || ' - available from APGL. Message us on WhatsApp to confirm price, availability, colour options and bulk pricing.', '{}'::jsonb, array[v.img], v.featured, false, true, now() - make_interval(mins => v.n)
